class Comando(ABC):
    @abstractmethod
    def ejecutar(self) -> None: ...

class Macro(Comando):
    """Compone múltiples comandos en uno."""

    def __init__(self, *comandos: Comando):
        self._cmds = list(comandos)

    def ejecutar(self) -> None:
        for cmd in self._cmds:
